from bk import write, OWNER_CONTACT

def legal(slug, title, desc, body, tags="legal"):
    write(f"/legal/{slug}.html", f"{title} | BetterKid.com", desc, f'''
<section class="section-tight"><div class="wrap article"><div class="crumbs"><a href="{{r}}">Home</a> › Legal › {title}</div><h1>{title}</h1><p class="lead">{desc}</p><p style="color:var(--muted);font-size:.9rem">Last updated: 27 September 2026</p>{body}
<p class="disclaimer">Questions about this page? <a href="{{r}}contact/">Contact us</a>. Enquiries about this website, the domain name, sponsorship, advertising or partnership: <a href="{OWNER_CONTACT}" target="_blank" rel="noopener">web.works/contact</a>.</p></div></section>''', tags)

def build():
    legal("trademark", "Trademark & Copyright Notice", "How the name “BetterKid” is used on this site, and our relationship (none) to other organisations with similar names.", f'''
<h2>Use of the name “BetterKid”</h2>
<p>“BetterKid” and “BetterKid.com” are used on this website as the descriptive name of an independent online publication about raising children. The words “better” and “kid” are ordinary English words; we use them in their plain, descriptive sense. We make no claim to exclusive rights in the words “better kid” or “better kids” as such, and nothing on this site should be taken as such a claim.</p>
<h2>No affiliation</h2>
<p>BetterKid.com is <strong>not affiliated with, sponsored by, endorsed by, or otherwise connected to</strong> any other company, non-profit, program, product or service that uses the words “Better Kid”, “Better Kids” or any similar name or mark. Without limitation, this includes:</p>
<ul><li><em>Better Kid Care</em>, a professional-development program of Penn State Extension (The Pennsylvania State University);</li><li><em>Better Kids Ltd.</em> and its “Wisdom: The World of Emotions” app (betterkids.education);</li><li><em>BetterKids</em> / betterkid.app;</li><li>The registered mark <em>“Better Parents. Better Kids.”</em> owned by The Raise Foundation;</li><li>Any therapy centre, clothing company, television program, school or other entity trading under a similar name, current or historical.</li></ul>
<p>If you were looking for one of those organisations, please use their own websites. If you represent one of them and have a concern about this notice, <a href="{{r}}contact/">contact us</a> and we will respond promptly and in good faith.</p>
<h2>Third-party trademarks</h2>
<p>All other product names, company names, logos and trademarks mentioned on this site — including Google, AdSense, YouTube, Amazon, PayPal, Ko-fi, Patreon, GitHub and any brands referenced in guides, gift guides or videos — are the property of their respective owners and are used only for identification and description (nominative fair use). No endorsement is implied in either direction.</p>
<h2>Copyright</h2>
<p>Original text, tools, printables, illustrations, code and video on BetterKid.com are © BetterKid.com, all rights reserved, except where noted. Parents, teachers, clinicians and schools may print and copy printables and short excerpts for personal, classroom or clinical use provided the BetterKid.com attribution is kept. Commercial reproduction, redistribution or republication requires written permission. Quotations from research are used under fair use/fair dealing with citation; if you are a rights-holder and believe something is used improperly, contact us and we will address it quickly.</p>
<h2>Content reviewed for infringement</h2>
<p>We do not knowingly reproduce copyrighted material, use others' logos, or copy the design or content of any other website. Where our research surveyed other parenting websites, we studied <em>categories of features</em> — not their content, code or design assets — and built BetterKid.com independently.</p>''', "trademark copyright legal notice")

    legal("privacy", "Privacy Policy", "What we collect, why, and how to control it. Short version: as little as possible, never sold.", '''
<h2>Who we are</h2><p>BetterKid.com (“we”) is an independent online publication. This policy covers betterkid.com and our newsletter.</p>
<h2>What we collect</h2>
<ul><li><strong>Forms you submit</strong> (newsletter, contact, contests, careers, sponsor enquiries): the fields you enter, the page you were on, and the time. Forms are relayed by FormSubmit.co to our inbox; see their <a href="https://formsubmit.co/privacy" rel="noopener" target="_blank">privacy policy</a>.</li><li><strong>Personalisation</strong>: your child-age selection, theme and “already subscribed” status are stored in your browser's local storage only. They never leave your device.</li><li><strong>Tools</strong>: all calculators and quizzes run entirely in your browser. We do not receive your inputs.</li><li><strong>Analytics &amp; advertising</strong>: if enabled, Google Analytics and Google AdSense use cookies and similar technologies to measure traffic and serve ads; see <a href="https://policies.google.com/technologies/partner-sites" rel="noopener" target="_blank">how Google uses data</a>. Embedded YouTube videos use the privacy-enhanced domain and load only when you press play.</li></ul>
<h2 id="cookies">Cookies and ads</h2><p>Third-party vendors, including Google, use cookies to serve ads based on prior visits to this or other websites. Google's use of advertising cookies enables it and its partners to serve ads based on your visits. You can opt out of personalised advertising at <a href="https://www.google.com/settings/ads" rel="noopener" target="_blank">Google Ads Settings</a> or <a href="https://www.aboutads.info" rel="noopener" target="_blank">aboutads.info</a>. Visitors in the EEA/UK see a consent prompt where required.</p>
<h2>How we use data</h2><p>To send what you asked for, answer you, run contests, improve the site, and serve advertising. We never sell personal data. We share it only with processors needed to operate (form relay, email delivery, analytics, ad serving) and where the law requires.</p>
<h2>Children</h2><p>BetterKid.com is for parents and carers. We do not knowingly collect personal information from children under 13. Contest entries about children (e.g. Wonder Art) are submitted by a parent, and we publish first name and age only, with consent.</p>
<h2>Your rights</h2><p>You may access, correct or delete your data, or withdraw consent, at any time by contacting us. Every newsletter has a one-click unsubscribe. Residents of the EEA, UK, Canada and California have additional rights under GDPR, PIPEDA and CCPA respectively, which we honour for everyone.</p>
<h2>Retention &amp; security</h2><p>We keep form submissions as long as needed for the purpose, then delete them. Data is transmitted over HTTPS.</p>
<h2>Changes</h2><p>We'll update the date above when this policy changes and note material changes in the newsletter.</p>''', "privacy policy cookies gdpr")

    legal("terms", "Terms of Use", "The rules for using BetterKid.com, its tools and printables.", '''
<h2>Acceptance</h2><p>By using BetterKid.com you agree to these terms. If you don't agree, please don't use the site.</p>
<h2>Educational information only</h2><p>Content and tools are general educational information for parents and carers. They are not medical, psychological, nutritional, educational, legal or financial advice, and do not create a professional relationship. Always consult a qualified professional about your child. In an emergency, contact local emergency services.</p>
<h2>Tools and calculators</h2><p>Tools produce estimates from published guidance and your inputs. Results may be inaccurate for your child's circumstances. Use them as conversation starters with professionals, not as decisions.</p>
<h2>Licence to use content</h2><p>You may view, print and share content for personal, non-commercial use, and print printables for personal, classroom or clinical use with attribution. You may not scrape, republish, sell or create derivative works from our content or code without permission.</p>
<h2>User submissions</h2><p>By submitting a tool idea, hack, question or contest entry you grant us a non-exclusive, royalty-free, worldwide licence to use, edit and publish it with attribution (first name), and confirm you have the right to do so. Contests are subject to the rules on the contests page.</p>
<h2>Third-party links</h2><p>We link to other sites, including affiliate links. We are not responsible for their content or practices.</p>
<h2>Disclaimer of warranties &amp; limitation of liability</h2><p>The site is provided “as is”. To the fullest extent permitted by law, we disclaim all warranties and are not liable for any loss or damage arising from use of the site or reliance on its content.</p>
<h2>Governing law</h2><p>These terms are governed by the laws of the Province of Québec and the federal laws of Canada applicable therein, without regard to conflict-of-law principles.</p>''', "terms conditions")

    legal("disclaimer", "Disclaimers & Affiliate Disclosure", "Medical, affiliate, advertising and AI-use disclosures in plain English.", '''
<h2>Medical &amp; professional disclaimer</h2><p>Nothing on BetterKid.com is medical, psychological, nutritional or legal advice. Content is reviewed against published guidance from bodies such as the American Academy of Pediatrics, American Academy of Sleep Medicine, CDC and WHO, but every child is different. Consult your paediatrician or a qualified professional before making decisions about your child's health, development, diet or education.</p>
<h2>Affiliate disclosure</h2><p>BetterKid.com participates in the Amazon Services LLC Associates Program and other affiliate programs. When you buy through links on our site we may earn a commission at no extra cost to you. Affiliate relationships never influence what we recommend; gift guides are compiled editorially and we disclose affiliate links on the pages where they appear.</p>
<h2>Advertising disclosure</h2><p>We display advertising, including through Google AdSense, and may publish sponsored content. Sponsored content is always labelled “Sponsored” or “Presented by”. Advertisers have no influence over editorial content. We decline advertisers in categories listed on our <a href="{r}sponsor/">partnerships page</a>.</p>
<h2>Support &amp; donations</h2><p>BetterKid.com is not a registered charity. Reader support is a voluntary contribution to keep the site free and is not tax-deductible.</p>
<h2>Use of AI</h2><p>We use AI tools for research assistance, drafting and code. Every published guide is reviewed and edited by a human who is accountable for its accuracy. Tools are tested by humans. If you find an error, <a href="{r}contact/">tell us</a> — we correct quickly and note material corrections.</p>
<h2>External links</h2><p>Links to third-party sites are provided for convenience; we don't control or endorse their content.</p>''', "disclaimer affiliate disclosure")

    legal("editorial-policy", "Editorial Policy", "How we choose topics, research, review and correct — and how we stay independent.", '''
<h2>Mission</h2><p>Help parents of 3–12 year-olds make one good decision tonight, with evidence they can check.</p>
<h2>Sourcing</h2><p>Guides cite primary sources — peer-reviewed research, professional-body guidance (AAP, AASM, CDC, WHO, NHS, Canadian Paediatric Society) and recognised experts. We prefer meta-analyses and consensus statements over single studies, and we say when evidence is mixed.</p>
<h2>Review</h2><p>Every guide and tool is checked against current guidance before publication and reviewed at least annually, or sooner when guidance changes. Content involving health, development or safety is reviewed by a qualified professional (paediatrician, psychologist, RN, OT, SLP or dietitian as appropriate). Reviewer roles are shown on each guide.</p>
<h2>Independence</h2><p>Advertisers, sponsors, affiliates and supporters never see content before publication and never influence conclusions. Sponsored content is labelled. Supporters vote on which tool we build next, not what it says.</p>
<h2>Corrections</h2><p>We correct errors promptly and note material corrections at the foot of the page. Send corrections via the <a href="{r}contact/">contact page</a>.</p>
<h2>AI &amp; tools</h2><p>AI assists with research and drafting; humans decide, verify and sign off. Interactive tools implement published formulas and thresholds, are tested against reference values, and state their assumptions on the page.</p>
<h2>Inclusivity</h2><p>We write for all parents and carers — mothers, fathers, grandparents, foster and adoptive parents, single parents and co-parents — in plain, gender-neutral language, and we avoid assuming any one family structure or culture.</p>''', "editorial policy standards")
